export type Budget = {
  spend: number
  limit: number | null
  softLimit: number | null
  duration: string | null
  resetAt: number | null
}

export type BudgetWindow = {
  duration: string
  spend: number | null
  limit: number
  resetAt: number | null
}

export type ModelBudget = {
  model: string
  spend: number
  limit: number | null
  period: string | null
}

export type KeyStatus = 'active' | 'expired' | 'revoked' | 'deleted' | 'unknown'

export type Limits = {
  rpm: number | null
  tpm: number | null
  tpd: number | null
  parallel: number | null
}

export type KeyInfo = {
  alias: string | null
  keyName: string | null
  keyHash: string | null
  status: KeyStatus
  budget: Budget
  lifetimeSpend: number | null
  windows: BudgetWindow[]
  modelBudgets: ModelBudget[]
  limits: Limits
  models: string[]
  expiresAt: number | null
  createdAt: number | null
  lastActiveAt: number | null
  userId: string | null
  teamId: string | null
  organizationId: string | null
  keyType: string | null
}

export type Related = {
  id: string
  label: string
  budget: Budget
  /** True when `budget.spend` is a lower bound: the proxy does not report the real figure to a virtual key. */
  isFloor?: boolean
}

/** Dollars per million tokens, and the context window, of one model the key can call. */
export type ModelPrice = {
  input: number | null
  output: number | null
  context: number | null
}

export type UsageDay = {
  date: string
  spend: number
}

/** What one model did on one day, or over a stretch of days. */
export type UsageModel = {
  model: string
  spend: number
  requests: number
  tokens: number
}

/** What the key did on one day: a quiet day is all zeros. */
export type ActivityDay = {
  /** `YYYY-MM-DD`, in UTC, as the proxy counts days. */
  date: string
  spend: number
  requests: number
  failed: number
  tokens: number
  inputTokens: number
  outputTokens: number
  cacheReadTokens: number
  models: UsageModel[]
}

/** The last 7 days in totals, and the last 30 day by day (oldest first, today last). */
export type Usage = {
  days: UsageDay[]
  spend: number
  requests: number
  tokens: number
  inputTokens: number
  outputTokens: number
  cacheReadTokens: number
  topModels: { model: string; spend: number }[]
  history: ActivityDay[]
}

/** What the proxy says about itself on its health endpoint, in the words it uses. */
export type ProxyInfo = {
  version: string | null
  /** `connected`, or whatever the proxy says when it has no database. */
  db: string | null
}

export type Snapshot = {
  fetchedAt: number
  host: string
  /** The proxy root that answered, without credentials: the page of its admin UI hangs off it. */
  root: string
  keySource: string
  keyHint: string
  key: KeyInfo
  user: Related | null
  /** The user's proxy role (proxy_admin, internal_user…), known even when the user has no budget cap. */
  userRole: string | null
  team: Related | null
  /** The per-member cap of the team (team_member_budget), for the key's user. */
  member: Related | null
  models: string[] | null
  /** Prices of the allowed models, by name; null when the proxy does not say. */
  prices: Record<string, ModelPrice> | null
  usage: Usage | null
  /** Read now and then, and only when the proxy answers: nothing here is worth a note when it does not. */
  proxy: ProxyInfo | null
  /** How long `/key/info` took to answer, when the reading could tell. */
  latencyMs: number | null
  notes: string[]
}

export type FailureKind =
  | 'not-configured'
  | 'not-litellm'
  | 'auth'
  | 'blocked'
  | 'expired'
  | 'forbidden'
  | 'not-found'
  | 'db'
  | 'rate-limit'
  | 'network'
  | 'http'

export type Failure = {
